arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -d "token=<TOKEN>" -d "channel=CRGEPRPXEAS" -d "limit=100" | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:',d.get('ok'))
for m in d.get('messages',[]):
    if m.get('is_reply') or m.get('thread_ts'):
        print('REPLY:', m['ts'], 'parent:', m.get('thread_ts'), repr(m.get('text',''))[:120])
    else:
        if 'rollback' in m.get('text','').lower():
            print('ROOT:', m['ts'], repr(m.get('text',''))[:120])
"

